SELECT * FROM ( SELECT DETAIL_DIST, BOOKSET_ID AS bookSetId, ( SELECT bb.ACCT_SUBJECT_ID FROM BOK_BOOKSET bb WHERE bb.BOOKSET_ID = BOK_VAL_TABLE_DATA.BOOKSET_ID) AS prodId, TO_CHAR(VAL_DATE,'YYYY-MM-DD') AS valDate, NVL(MARKET_VALUE, to_number(REGEXP_REPLACE(BOK_VAL_TABLE_DATA.SUBJECT_NAME,'[^0-9|.]',''))) MARKET_VALUE FROM BOK_VAL_TABLE_DATA WHERE BOOKSET_ID IN ( SELECT bookset_id FROM BOK_BOOKSET WHERE ACCT_MODE = '03') AND BOOKSET_ID in
#{item, jdbcType=VARCHAR}
AND VAL_DATE = #{exeDate, jdbcType=TIMESTAMP} AND DETAIL_DIST IN ('02','07','31','33','28','29','05','06') ) PIVOT ( MAX(MARKET_VALUE) FOR DETAIL_DIST IN ('02' AS prodAllAmt , '28' AS nowDayProfitValue, '29' AS nowDayRate, '31' AS totalRate, '33' AS sevenDayRate, '06' AS dailyAllDebt, '05' AS dailyAssetAllValue))
